package io.github.rebrowser.review;
import static org.junit.Assert.*;
import io.github.rebrowser.ui.*;
import io.github.rebrowser.music.*;
import io.github.rebrowser.lyrics.*;
import io.github.rebrowser.outlook.*;
import io.github.rebrowser.core.TaskSnapshot;
import java.lang.reflect.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.Test;
/** Actual nested presentation/ownership MODELS, no Android Views/Bitmap/Notification SDK calls. */
public final class D03MainUiModelsRegressionTest {
 private static TaskSnapshot success(){return TaskSnapshot.fromNativeEvidence(TaskSnapshot.Phase.OUTCOME_OBSERVED,TaskSnapshot.Work.ENDED,TaskSnapshot.Effect.OBSERVED_SUCCESS,TaskSnapshot.Durability.COMMITTED,TaskSnapshot.ClientWait.WAITING,false,true);}
 private static TaskSnapshot running(){return TaskSnapshot.fromNativeEvidence(TaskSnapshot.Phase.WORK_STARTED,TaskSnapshot.Work.RUNNING,TaskSnapshot.Effect.NOT_DISPATCHED,TaskSnapshot.Durability.NOT_COMMITTED,TaskSnapshot.ClientWait.WAITING,false,true);}
 @Test public void offeredFileHandoffNeverMeansPublished(){DownloadsAdapter.Row row=new DownloadsAdapter.Row(new Object(),"x",100,100,success(),false,true);assertTrue(DownloadsAdapter.Rows.canRequestHandoff(row));assertFalse(DownloadsActivity.Filter.PUBLISHED.matches(row));}
 @Test public void runningOrUnknownPhaseDoesNotProveActualOwnedSlot(){DownloadsAdapter.Row row=new DownloadsAdapter.Row(new Object(),"x",100,10,running(),false,false);assertFalse(DownloadsActivity.Filter.OCCUPIED.matches(row));DownloadsAdapter.Row observed=new DownloadsAdapter.Row(new Object(),"x",100,10,running(),false,false,null,true);assertTrue(DownloadsActivity.Filter.OCCUPIED.matches(observed));}
 @Test public void filteringCannotReenableSpentCancel(){DownloadsAdapter.Row row=new DownloadsAdapter.Row(new Object(),"x",100,1,running(),false,false);DownloadsAdapter.Row reduced=row.suppressUiActions(EnumSet.of(DownloadsAdapter.RowAction.CANCEL));assertTrue(DownloadsAdapter.Rows.canRequestCancel(row));assertFalse(DownloadsAdapter.Rows.canRequestCancel(reduced));assertSame(row.itemRef(),reduced.itemRef());assertSame(row.snapshot(),reduced.snapshot());}
 @Test public void historyLatchRejectsUnknownOrUnOfferedTargets(){HistoryAdapter.State state=new HistoryAdapter.State();Object token=new Object();Object frame=state.show(1,Arrays.asList(new HistoryAdapter.Row(token,"t","u","v")));assertFalse(state.beginAttempt(frame,1,new Object(),HistoryAdapter.Offered.OPEN));assertFalse(state.beginAttempt(frame,1,token,HistoryAdapter.Offered.REMOVE));}
 @Test public void downloadLatchCannotApproveRunningOrHandoffUnknownOutcome(){DownloadsAdapter.State state=new DownloadsAdapter.State();Object token=new Object();Object frame=state.show(1,Arrays.asList(new DownloadsAdapter.Row(token,"f",10,1,running(),true,true)));assertFalse(state.beginAttempt(frame,1,token,DownloadsAdapter.RowAction.APPROVE));assertFalse(state.beginAttempt(frame,1,token,DownloadsAdapter.RowAction.HANDOFF));assertFalse(state.beginAttempt(frame,1,new Object(),DownloadsAdapter.RowAction.CANCEL));}
 @Test public void navigationRowsAreNotInventedBooleanPreferences(){for(String id:new String[]{"ui.row.general.preferences","ui.row.general.startup","ui.row.subapplications.enabled"})assertEquals(SettingsSections.ValueKind.READ_ONLY,SettingsSections.requireRow(id).kind());assertThrows(IllegalArgumentException.class,()->new SettingsActivity.EditSession(1).setBoolean("ui.row.general.preferences",true));}
 @Test public void settingsHaveOneNativeBatchCallbackNotPartialMutationLoop(){Method method=null;for(Method m:SettingsActivity.Actions.class.getMethods()){assertFalse(m.getName().equals("onChange"));if(m.getName().equals("onChanges"))method=m;}assertNotNull(method);assertArrayEquals(new Class<?>[]{List.class,long.class},method.getParameterTypes());}
 @Test public void observedSettingsProjectionRejectsUnknownKeysAndHugeValue(){assertThrows(IllegalArgumentException.class,()->new SettingsActivity.Observed(Collections.singletonMap("ui.unknown",true),1));assertThrows(IllegalArgumentException.class,()->new SettingsActivity.Observed(Collections.emptyMap(),Collections.singletonMap("ui.row.search.engine",new String(new char[100000])),Collections.emptyMap(),1));}
 @Test public void equalLabelsCannotMergeUnknownNativeSiteScopes(){SitePermissionsActivity.Row a=site(new Object(),null),b=site(new Object(),null);assertEquals(2,SitePermissionsActivity.Groups.of(new SitePermissionsActivity.Page(Arrays.asList(a,b),1)).size());Object scope=new Object();assertEquals(1,SitePermissionsActivity.Groups.of(new SitePermissionsActivity.Page(Arrays.asList(site(new Object(),scope),site(new Object(),scope)),1)).size());}
 private static SitePermissionsActivity.Row site(Object row,Object scope){return new SitePermissionsActivity.Row(row,"site.invalid","same-label",SitePermissionsActivity.Capability.CAMERA,SitePermissionsActivity.Expiry.UNKNOWN,0,SitePermissionsActivity.OsState.UNKNOWN,Collections.emptySet(),scope);}
 @Test public void offlineQueryDoesNotLeakOrAcceptMalformedText(){assertFalse(new OfflineMailActivity.Query("private literal",0).toString().contains("private"));assertThrows(IllegalArgumentException.class,()->new OfflineMailActivity.Query(new String(new char[100000]).replace('\0',' '),0));assertThrows(IllegalArgumentException.class,()->new OfflineMailActivity.Query("\ud800",0));}
 @Test public void offlineReceiptCannotBeMintedFromPublicQueryOrBoolean(){assertEquals(0,OfflineMailActivity.Presentation.class.getConstructors().length);assertEquals(0,OfflineMailActivity.BodyRequest.class.getConstructors().length);}
 @Test public void artworkOldOwnerCannotFreeNewOwnerEvenAfterAba()throws Exception{MusicArtwork artwork=new MusicArtwork();Class<?> slot=Class.forName("io.github.rebrowser.music.MusicArtwork$Slot");Constructor<?> constructor=slot.getDeclaredConstructor();constructor.setAccessible(true);Object a=constructor.newInstance(),b=constructor.newInstance();Field field=MusicArtwork.class.getDeclaredField("active");field.setAccessible(true);@SuppressWarnings("unchecked") AtomicReference<Object> owner=(AtomicReference<Object>)field.get(artwork);Method release=MusicArtwork.class.getDeclaredMethod("releaseSlot",slot);release.setAccessible(true);owner.set(a);assertEquals(Boolean.TRUE,release.invoke(artwork,a));owner.set(b);assertEquals(Boolean.FALSE,release.invoke(artwork,a));assertSame(b,owner.get());}
 @Test public void zeroAndStaleArtworkGenerationCannotReachSdk(){MusicArtwork artwork=new MusicArtwork();assertThrows(IllegalArgumentException.class,()->artwork.decodeOwned(new byte[16],0));assertEquals(5,artwork.begin(5));assertEquals(0,artwork.begin(4));assertTrue(Modifier.isSynchronized(Arrays.stream(MusicArtwork.OwnedBitmap.class.getDeclaredMethods()).filter(m->m.getName().equals("release")).findFirst().get().getModifiers()));}
 @Test public void notificationSnapshotIsTakenOnceAndDropsOldPrivateMetadata()throws Exception{MusicNotification.Snapshot snapshot=MusicNotification.Snapshot.of(new MusicNotification.Projection("private title","artist",false,0,-1),Collections.emptyList());AtomicInteger taken=new AtomicInteger();List<Thread> threads=new ArrayList<>();for(int i=0;i<16;i++){Thread t=new Thread(()->{if(snapshot.take())taken.incrementAndGet();});threads.add(t);t.start();}for(Thread t:threads)t.join(2000);for(Thread t:threads)assertFalse(t.isAlive());assertEquals(1,taken.get());assertTrue(snapshot.projection().title().isEmpty());assertTrue(snapshot.actions().isEmpty());}
 @Test public void foreignEstimateCannotReplaceCurrentMediaDisplay(){MusicState a=state(),b=state();MusicState.Estimate estimate=a.estimatePosition(1,200,1d);MusicMediaSession.Projection projection=MusicMediaSession.project(b,Collections.emptySet(),estimate);assertNull(projection.estimatedPositionMs());assertFalse(projection.reportedSpeedKnown());}
 private static MusicState state(){return new MusicState(MusicState.Account.UNKNOWN,MusicState.Playback.PLAYING,MusicState.Focus.NONE,"t","a",null,0,1000,1,0);}
 @Test public void displayArithmeticCannotOverflowOrCreateSeekPermission(){assertThrows(IllegalArgumentException.class,()->MusicActivity.Model.progressPermille(Long.MAX_VALUE,1));assertThrows(IllegalArgumentException.class,()->MusicActivity.Model.seekTarget(Long.MAX_VALUE,1000));assertFalse(MusicActivity.Model.seekEnabled(state()));assertTrue(MusicActivity.Model.seekEnabled(state(),true));}
 @Test public void dragStartFailureDoesNotInstallAPartialGesture(){LyricOverlayWindow.DragModel drag=new LyricOverlayWindow.DragModel(500,500,160,160);assertThrows(IllegalArgumentException.class,()->drag.start(-1,1,0,0,0,0));assertFalse(drag.active());assertThrows(IllegalArgumentException.class,()->drag.start(1,1,0,0,Integer.MAX_VALUE,0));assertFalse(drag.active());}
}
